=== FILE: skid_buffer.v ===
// skid_buffer: register slice for one valid/ready stream.
// Implements microarchitecture.md (two registers: output + skid) for the
// interface in interface_spec.md. Every output is a flop or the inverse of
// one; the inputs reach only next-state logic.
`timescale 1ns/1ps
`default_nettype none

module skid_buffer #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Upstream ready is the inverse of a flop.
    assign s_ready = ~skid_valid;

    // m_free: the output register may load on this edge.
    wire m_free = (~m_valid) | m_ready;
    // s_fire: an upstream beat is accepted on this edge.
    wire s_fire = s_valid & (~skid_valid);

    // Next state (microarchitecture.md section 3).
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // Move the skid beat to the output; skid empties.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Load the input directly; valid follows s_valid.
                m_valid_d    = s_valid;
                m_data_d     = s_data;
            end
        end else if (s_fire) begin
            // Output stalled: catch the accepted beat in the skid register.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: no reset (microarchitecture.md section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    // Design-intent assertions (not a submitted proof setup).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // The skid register is full only while the output register is.
            if (skid_valid) assert(m_valid);
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end else begin
                // Hold: a stalled beat stays offered with the same data.
                if ($past(m_valid) && !$past(m_ready)) begin
                    assert(m_valid);
                    assert(m_data == $past(m_data));
                end
                // A beat accepted while stalled lands in the skid register.
                if ($past(s_valid) && $past(s_ready) && $past(m_valid) && !$past(m_ready)) begin
                    assert(skid_valid);
                    assert(skid_data == $past(s_data));
                end
            end
        end
    end
`endif

endmodule

`default_nettype wire
