// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Stimulus changes 1 ns after each negedge; the model is stepped and the
// outputs checked at each negedge; outputs are probed for combinational
// paths between negedge+2 and negedge+4, before the next posedge.
`timescale 1ns/1ps
`default_nettype none

`define CHK(ok, pc, fc, msg) \
    begin \
        if (ok) pc = pc + 1; \
        else begin \
            fc = fc + 1; \
            $error("%0t: %0s", $time, msg); \
        end \
    end

module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;
    reg        g_mr;
    reg        g_sv;

    wire       dut_s_valid = s_valid ^ g_sv;
    wire       dut_m_ready = m_ready ^ g_mr;
    wire [7:0] dut_s_data8 = s_data ^ {8{g_sv}};
    wire [0:0] dut_s_data1 = dut_s_data8[0:0];

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) u_w8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (dut_s_valid),
        .s_ready (s_ready8),
        .s_data  (dut_s_data8),
        .m_valid (m_valid8),
        .m_ready (dut_m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) u_w1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (dut_s_valid),
        .s_ready (s_ready1),
        .s_data  (dut_s_data1),
        .m_valid (m_valid1),
        .m_ready (dut_m_ready),
        .m_data  (m_data1)
    );

    // Clock
    initial clk = 1'b0;
    always #5 clk = ~clk;

    // ---------------- Model and per-cycle check ----------------
    integer    c_passed;
    integer    c_failed;
    reg  [1:0] cnt;
    reg  [7:0] q0;
    reg  [7:0] q1;
    reg        model_known;
    reg        prev_known;
    reg        prev_mv8;
    reg  [7:0] prev_md8;
    reg        prev_mv1;
    reg  [0:0] prev_md1;
    reg        sf;
    reg        mf;
    integer    tx_count;
    integer    rx_count;
    integer    dropped;
    integer    full_seen;

    initial begin : model_check
        c_passed    = 0;
        c_failed    = 0;
        cnt         = 2'd0;
        q0          = 8'h00;
        q1          = 8'h00;
        model_known = 1'b0;
        prev_known  = 1'b0;
        prev_mv8    = 1'b0;
        prev_md8    = 8'h00;
        prev_mv1    = 1'b0;
        prev_md1    = 1'b0;
        sf          = 1'b0;
        mf          = 1'b0;
        tx_count    = 0;
        rx_count    = 0;
        dropped     = 0;
        full_seen   = 0;
        forever begin
            @(negedge clk);
            if (!rst_n) begin
                if (cnt == 2'd2) dropped = dropped + 2;
                else if (cnt == 2'd1) dropped = dropped + 1;
                cnt         = 2'd0;
                model_known = 1'b1;
            end else if (model_known) begin
                // Hold rule: a beat offered and not taken stays offered.
                if (prev_known && prev_mv8 && !m_ready) begin
                    `CHK((m_valid8 === 1'b1) && (m_data8 === prev_md8), c_passed, c_failed, "hold rule broken (WIDTH 8)")
                end
                if (prev_known && prev_mv1 && !m_ready) begin
                    `CHK((m_valid1 === 1'b1) && (m_data1 === prev_md1), c_passed, c_failed, "hold rule broken (WIDTH 1)")
                end
                sf = s_valid && (cnt != 2'd2);
                mf = m_ready && (cnt != 2'd0);
                if (mf) begin
                    q0       = q1;
                    cnt      = cnt - 2'd1;
                    rx_count = rx_count + 1;
                end
                if (sf) begin
                    if (cnt == 2'd0) q0 = s_data;
                    else q1 = s_data;
                    cnt      = cnt + 2'd1;
                    tx_count = tx_count + 1;
                end
                if (cnt == 2'd2) full_seen = full_seen + 1;
            end
            if (model_known) begin
                `CHK((m_valid8 === (cnt != 2'd0)) && (m_valid1 === (cnt != 2'd0)), c_passed, c_failed, "m_valid disagrees with the model")
                `CHK((s_ready8 === (cnt != 2'd2)) && (s_ready1 === (cnt != 2'd2)), c_passed, c_failed, "s_ready disagrees with the model")
                if (cnt != 2'd0) begin
                    `CHK(m_data8 === q0, c_passed, c_failed, "m_data is not the oldest beat (WIDTH 8)")
                    `CHK(m_data1 === q0[0:0], c_passed, c_failed, "m_data is not the oldest beat (WIDTH 1)")
                end
            end
            prev_known = model_known;
            prev_mv8   = m_valid8;
            prev_md8   = m_data8;
            prev_mv1   = m_valid1;
            prev_md1   = m_data1;
        end
    end

    // ---------------- Combinational-path probe ----------------
    integer    g_passed;
    integer    g_failed;
    reg        sr8_s;
    reg        mv8_s;
    reg  [7:0] md8_s;
    reg        sr1_s;
    reg        mv1_s;
    reg  [0:0] md1_s;

    initial begin : glitch_probe
        g_passed = 0;
        g_failed = 0;
        g_mr     = 1'b0;
        g_sv     = 1'b0;
        forever begin
            @(negedge clk);
            #2;
            sr8_s = s_ready8;
            mv8_s = m_valid8;
            md8_s = m_data8;
            sr1_s = s_ready1;
            mv1_s = m_valid1;
            md1_s = m_data1;
            g_mr = 1'b1;
            #1;
            `CHK((s_ready8 === sr8_s) && (s_ready1 === sr1_s), g_passed, g_failed, "s_ready moved with m_ready inside a cycle")
            `CHK((m_valid8 === mv8_s) && (m_valid1 === mv1_s), g_passed, g_failed, "m_valid moved with m_ready inside a cycle")
            `CHK((m_data8 === md8_s) && (m_data1 === md1_s), g_passed, g_failed, "m_data moved with m_ready inside a cycle")
            g_mr = 1'b0;
            g_sv = 1'b1;
            #1;
            `CHK((s_ready8 === sr8_s) && (s_ready1 === sr1_s), g_passed, g_failed, "s_ready moved with s_valid inside a cycle")
            `CHK((m_valid8 === mv8_s) && (m_valid1 === mv1_s), g_passed, g_failed, "m_valid moved with s_valid inside a cycle")
            `CHK((m_data8 === md8_s) && (m_data1 === md1_s), g_passed, g_failed, "m_data moved with s_valid/s_data inside a cycle")
            g_sv = 1'b0;
        end
    end

    // ---------------- Directed and random stimulus ----------------
    integer          d_passed;
    integer          d_failed;
    integer          passed;
    integer          failed;
    integer          i;
    reg  [7:0]       k;
    reg  [7:0]       exp_d;
    reg  [31:0]      rng;
    reg  [8*64-1:0]  nonce;

    task cyc;
        begin
            @(negedge clk);
            #1;
        end
    endtask

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task expect_out;
        input       exp_mv;
        input       exp_sr;
        input [7:0] exp_md;
        begin
            `CHK((m_valid8 === exp_mv) && (m_valid1 === exp_mv), d_passed, d_failed, "m_valid differs from the directed expectation")
            `CHK((s_ready8 === exp_sr) && (s_ready1 === exp_sr), d_passed, d_failed, "s_ready differs from the directed expectation")
            if (exp_mv) begin
                `CHK((m_data8 === exp_md) && (m_data1 === exp_md[0:0]), d_passed, d_failed, "m_data differs from the directed expectation")
            end
        end
    endtask

    initial begin : directed
        d_passed = 0;
        d_failed = 0;
        passed   = 0;
        failed   = 0;
        rng      = 32'h1F2E3D4C;
        k        = 8'h00;
        exp_d    = 8'h00;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

        // Reset values
        rst_n   = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data  = 8'h00;
        cyc;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);

        // Reset dominates an offered beat
        s_valid = 1'b1;
        s_data  = 8'hEE;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);

        // Release reset, idle
        rst_n   = 1'b1;
        s_valid = 1'b0;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);

        // One-cycle latency: not offered before the edge, offered after it
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b0;
        expect_out(1'b0, 1'b1, 8'h00);
        cyc;
        expect_out(1'b1, 1'b1, 8'hA5);

        // Stall with one beat held: a second beat must be accepted
        s_data = 8'h3C;
        cyc;
        expect_out(1'b1, 1'b0, 8'hA5);

        // Stall with two held: a third must not be accepted
        s_data = 8'hFF;
        cyc;
        expect_out(1'b1, 1'b0, 8'hA5);
        cyc;
        expect_out(1'b1, 1'b0, 8'hA5);
        cyc;
        expect_out(1'b1, 1'b0, 8'hA5);

        // Ready rises: beats leave in order, each once, no bubble
        m_ready = 1'b1;
        s_data  = 8'h77;
        cyc;
        expect_out(1'b1, 1'b1, 8'h3C);
        cyc;
        expect_out(1'b1, 1'b1, 8'h77);
        s_valid = 1'b0;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);

        // Full throughput: one beat in and one out on every edge
        for (i = 0; i < 32; i = i + 1) begin
            k       = i[7:0];
            exp_d   = k + 8'h40;
            s_valid = 1'b1;
            s_data  = exp_d;
            m_ready = 1'b1;
            `CHK((s_ready8 === 1'b1) && (s_ready1 === 1'b1), d_passed, d_failed, "s_ready low during full-throughput stream")
            cyc;
            expect_out(1'b1, 1'b1, exp_d);
        end
        s_valid = 1'b0;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);

        // Random traffic against the model, with a reset during traffic
        for (i = 0; i < 1500; i = i + 1) begin
            next_rand;
            s_valid = rng[0] | rng[1];
            if (i < 500) m_ready = rng[2] | rng[3];
            else if (i < 1000) m_ready = rng[2] & rng[3];
            else m_ready = rng[2];
            s_data = rng[15:8];
            if (i == 700) rst_n = 1'b0;
            else rst_n = 1'b1;
            cyc;
        end

        // Drain
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        cyc;
        cyc;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);
        `CHK(cnt == 2'd0, d_passed, d_failed, "model not empty after drain")
        `CHK(tx_count == rx_count + dropped, d_passed, d_failed, "beats accepted and delivered do not balance")
        `CHK(full_seen > 0, d_passed, d_failed, "random traffic never filled the slice")
        `CHK(tx_count > 500, d_passed, d_failed, "random traffic moved too few beats")

        // Reset with two beats held
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h81;
        cyc;
        expect_out(1'b1, 1'b1, 8'h81);
        s_data = 8'h82;
        cyc;
        expect_out(1'b1, 1'b0, 8'h81);
        rst_n  = 1'b0;
        s_data = 8'h83;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);
        rst_n  = 1'b1;
        s_data = 8'h84;
        cyc;
        expect_out(1'b1, 1'b1, 8'h84);
        s_valid = 1'b0;
        m_ready = 1'b1;
        cyc;
        expect_out(1'b0, 1'b1, 8'h00);
        cyc;
        cyc;

        passed = c_passed + g_passed + d_passed;
        failed = c_failed + g_failed + d_failed;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
